macro.command:
const castId = "dnd5eactivity000";
const sustainId = "tQNWZvNjROa3NT5n";
const casterEffectId = "cpEnervationSelf";
const targetEffectId = "g3BL9EqiAeBO2lIB";
const hiddenPath = `system.activities.${sustainId}.flags.dnd5e_classpack.hidden`;
const linkPath = "flags.dnd5e_classpack.enervation";

function connected(link) {
  const source = fromUuidSync(link.source);
  const target = fromUuidSync(link.target);
  if (!source || !target || source.parent !== target.parent || target.actor.statuses.has("coverTotal")) return false;
  if (!source.object || !target.object) return true;
  const distance = MidiQOL.getDistance(source.object, target.object, { wallsBlock: true, includeCover: true });
  return distance >= 0 && distance <= link.range && MidiQOL.computeCoverBonus(source.object, target.object) !== Infinity;
}

async function endConcentration(uuid) {
  const effect = fromUuidSync(uuid);
  if (!effect) return;
  if (effect.parent.isOwner) await effect.parent.endConcentration(effect.id);
  else await MidiQOL.removeEffects({ actorUuid: effect.parent.uuid, effects: [effect.id] });
}

if (args[0] === "off") {
  const data = args.at(-1).efData;
  const link = data.flags.dnd5e_classpack?.enervation;
  if (!link) return;
  if (data.system.origin.profile === casterEffectId) {
    const spell = await fromUuid(macroItem.uuid);
    if (spell?.getFlag("dnd5e_classpack", "enervation")?.concentration === link.concentration) {
      await spell.update({ [hiddenPath]: true, "flags.dnd5e_classpack.-=enervation": null });
    }
  }
  await endConcentration(link.concentration);
  return;
}
if (args[0] === "on") return;

const pass = args[0].macroPass;
const spell = await fromUuid(macroItem.uuid);
const caster = workflow.actor;
const activityId = workflow.activity.id;
const sustained = activityId === sustainId;
const link = spell.getFlag("dnd5e_classpack", "enervation");
const combat = game.combat;
const combatant = combat?.started && combat.combatants.find(entry => entry.token?.uuid === link?.source);
const turn = combatant ? `${combat.id}:${combat.round}:${combat.turn}` : null;

if (pass === "preTargeting") {
  if (!sustained) return;
  if (!link || !fromUuidSync(link.concentration)?.active) return false;
  if (!connected(link)) {
    await endConcentration(link.concentration);
    return false;
  }
  if (combatant && (combat.combatant !== combatant || link.lastTurn === turn)) {
    ui.notifications.warn("汲能术：只能在自己的回合持续汲能一次。");
    return false;
  }
  const midiOptions = args[0].options.usage.midiOptions;
  midiOptions.targetsToUse = new MidiQOL.TokenDocumentSet([fromUuidSync(link.target)]);
  midiOptions.workflowOptions.targetConfirmation = "never";
  return;
}

if (pass === "postPreambleComplete") {
  if (!link || workflow.aborted || workflow.outcome === "invalid" || workflow.item.uuid === spell.uuid) return;
  const options = workflow.workflowOptions;
  if (workflow.itemUsesReaction || workflow.itemUsesBonusAction || options.castUsesReaction || options.castUsesBonusAction) return;
  if (workflow.activity.effectiveActivationType === "action") await endConcentration(link.concentration);
  return;
}

if (pass !== "postActiveEffects" || workflow.aborted || workflow.outcome === "invalid") return;
const target = workflow.targets.documents[0];
if (!target) return;

if (activityId === castId) {
  const concentration = caster.effects.get(workflow.concentrationId);
  if (link && link.concentration !== concentration?.uuid) await endConcentration(link.concentration);
  if (concentration?.active && workflow.saves.has(target)) {
    await caster.endConcentration(concentration.id);
  } else if (concentration?.active && workflow.failedSaves.has(target)) {
    const fromThisCast = (effect, profile) => effect.active
      && effect.system.origin?.effect === concentration.uuid && effect.system.origin.profile === profile;
    const sourceEffect = caster.effects.find(effect => fromThisCast(effect, casterEffectId));
    const targetEffect = target.actor.effects.find(effect => fromThisCast(effect, targetEffectId));
    const state = {
      concentration: concentration.uuid, source: workflow.tokenDocument.uuid, target: target.uuid,
      range: MidiQOL.checkActivityRange(workflow.activity, workflow.token, new Set([target]), false).range
        ?? Number(workflow.activity.range.value),
      lastTurn: null
    };

    if (!sourceEffect || !targetEffect || !connected(state)) {
      await caster.endConcentration(concentration.id);
    } else {
      const condition = `(${connected.toString()})(effect.flags.dnd5e_classpack.enervation)`;
      await sourceEffect.update({
        [linkPath]: state,
        "flags.dae.enableCondition": condition,
        "system.changes": [...sourceEffect.toObject().system.changes, {
          key: "flags.midi-qol.onUseMacroName", value: `[postPreambleComplete]ItemMacro.${spell.uuid}`,
          type: "add", phase: "initial", priority: 20
        }]
      });
      await MidiQOL.updateEffects({ actorUuid: target.actor.uuid, updates: [{
        _id: targetEffect.id, [linkPath]: state, "flags.dae.enableCondition": condition
      }] });

      const parts = spell.system.activities.get(sustainId).toObject().damage.parts;
      parts[0].number = 4 + Math.max(0, workflow.spellLevel - spell.system.level);
      if (fromUuidSync(concentration.uuid)?.active) await spell.update({
        [linkPath]: state,
        [hiddenPath]: false,
        [`system.activities.${sustainId}.damage.parts`]: parts
      });
    }
  }
} else if (sustained) {
  if (turn && link) await spell.update({ [`${linkPath}.lastTurn`]: turn });
} else return;

const { autoApplyDamage } = MidiQOL.configSettings();
if (!autoApplyDamage.includes("yes") || (autoApplyDamage === "yesCardNPC" && target.actor.type === "character")) return;
const damage = workflow.damageList?.find(row => row.wasHit && row.targetUuid === target.uuid);
if (!damage) return;

const absorbed = part => part.active?.absorption || part.active?.type?.absorption;
const { defaultDamage, combinedDamage } = damage.damageDetails;
const necrotic = defaultDamage
  .filter(part => part.type === "necrotic" && part.value > 0 && !absorbed(part))
  .reduce((total, part) => total + part.value, 0);
const total = combinedDamage
  .filter(part => !["healing", "temphp", "maximum", "vitality", "midi-none"].includes(part.type) && !absorbed(part))
  .reduce((sum, part) => sum + part.value, 0);
const dealt = Math.min(necrotic, total);
const healing = Math.floor(dealt / 2);
if (healing <= 0) return;

const healingDamage = [{ value: healing, type: "healing", properties: new Set(["mgc"]) }];
if (autoApplyDamage === "yesCardNPC" && caster.type === "character") {
  await caster.applyDamage(healingDamage);
} else {
  await MidiQOL.applyTokenDamage(
    healingDamage, healing, new MidiQOL.TokenDocumentSet([workflow.tokenDocument]),
    spell, new MidiQOL.TokenDocumentSet(), { workflow }
  );
}

const card = workflow.chatCard;
if (card) await MidiQOL.addCardNote(card, `<p>汲能术：${dealt} 点暗蚀伤害，回复 ${healing} 点生命值。</p>`, {
  anchor: "bottom", key: "classpack-enervation-healing",
  whisper: card.blind ? game.users.filter(user => user.isGM).map(user => user.id) : card.whisper
});
